const index = {
  documentCount: 4,
  docLengths: { a: 6, b: 6, c: 5, d: 3 },
  postings: { cat: { a: 1, c: 2 }, the: { a: 2, b: 1, d: 1 } }
};

function termFrequency(index, term, docId) {
  const length = index.docLengths[docId];
  if (!length) return 0;
  const posting = index.postings[term];
  return (posting && posting[docId] ? posting[docId] : 0) / length;
}

function inverseDocumentFrequency(index, term) {
  const posting = index.postings[term];
  const df = posting ? Object.keys(posting).length : 0;
  return df === 0 ? 0 : Math.log(index.documentCount / df);
}

function show(term, id) {
  const tf = termFrequency(index, term, id);
  const idf = inverseDocumentFrequency(index, term);
  return term + " in " + id + ": tf=" + tf.toFixed(4) + " idf=" + idf.toFixed(4) +
         " tfidf=" + (tf * idf).toFixed(4);
}

