function tokenise(text) {
  const raw = text === null || text === undefined ? "" : String(text);
  return raw.toLowerCase().split(/[^a-z0-9]+/).filter(function (t) { return t.length > 0; });
}

function buildIndex(documents) {
  const docs = documents || [];
  const index = { documentCount: docs.length, docLengths: {}, postings: {} };
  for (const doc of docs) {
    const tokens = tokenise(doc.text);
    index.docLengths[doc.id] = tokens.length;
    for (const term of tokens) {
      if (!index.postings[term]) index.postings[term] = {};
      index.postings[term][doc.id] = (index.postings[term][doc.id] || 0) + 1;
    }
  }
  return index;
}

function termFrequency(index, term, docId) {
  const length = index.docLengths[docId];
  if (!length) return 0;
  const posting = index.postings[term];
  const count = posting ? posting[docId] || 0 : 0;
  return count / length;
}

function inverseDocumentFrequency(index, term) {
  const posting = index.postings[term];
  const df = posting ? Object.keys(posting).length : 0;
  if (df === 0) return 0;
  return Math.log(index.documentCount / df);
}

function parseQuery(query) {
  const parsed = { required: [], optional: [], excluded: [] };
  const seen = [];
  const raw = query === null || query === undefined ? "" : String(query);
  for (const word of raw.split(/\s+/).filter(Boolean)) {
    let bucket = "optional", rest = word;
    if (word[0] === "+") { bucket = "required"; rest = word.slice(1); }
    else if (word[0] === "-") { bucket = "excluded"; rest = word.slice(1); }
    for (const term of tokenise(rest)) {
      if (seen.indexOf(term) >= 0) continue;
      seen.push(term);
      parsed[bucket].push(term);
    }
  }
  return parsed;
}

function search(index, query) {
  const parsed = parseQuery(query);
  const scoring = parsed.required.concat(parsed.optional);
  if (scoring.length === 0) return [];
  const idf = {};
  for (const term of scoring) idf[term] = inverseDocumentFrequency(index, term);
  const hits = [];
  for (const id of Object.keys(index.docLengths)) {
    let allowed = true;
    for (const term of parsed.required) {
      if (termFrequency(index, term, id) === 0) allowed = false;
    }
    for (const term of parsed.excluded) {
      if (termFrequency(index, term, id) > 0) allowed = false;
    }
    if (!allowed) continue;
    let matched = 0, score = 0;
    for (const term of scoring) {
      const tf = termFrequency(index, term, id);
      if (tf > 0) matched += 1;
      score += tf * idf[term];
    }
    if (matched === 0) continue;
    hits.push({ id: id, score: score });
  }
  hits.sort(function (a, b) {
    if (b.score !== a.score) return b.score - a.score;
    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
  });
  return hits.map(function (h) { return h.id; });
}
